const listInsightsVelocity = `-- name: ListInsightsVelocity :many
SELECT
    date_trunc($1::text, d)::date AS period,
    coalesce(sum(v.added), 0)::int   AS added,
    coalesce(sum(v.removed), 0)::int AS removed
FROM generate_series($2::timestamp, $3::timestamp, interval '1 day') AS d
LEFT JOIN insights_velocity_daily v
    ON v.day = d::date
   AND v.facet_kind = $4
   AND v.facet_value = $5
GROUP BY date_trunc($1::text, d)
ORDER BY date_trunc($1::text, d)
`

type ListInsightsVelocityParams struct {
	Unit       string           `json:"unit"`
	FromTs     pgtype.Timestamp `json:"from_ts"`
	ToTs       pgtype.Timestamp `json:"to_ts"`
	FacetKind  string           `json:"facet_kind"`
	FacetValue string           `json:"facet_value"`
}

type ListInsightsVelocityRow struct {
	Period  pgtype.Date `json:"period"`
	Added   int32       `json:"added"`
	Removed int32       `json:"removed"`
}

// Dense, gap-free added/removed series over [from_ts, to_ts] at @unit granularity
// for one facet slice. A daily generate_series fills missing days with zeros; @unit
// is a caller-validated date_trunc field (day/week/month).
func (q *Queries) ListInsightsVelocity(ctx context.Context, arg ListInsightsVelocityParams) ([]ListInsightsVelocityRow, error) {
	rows, err := q.db.Query(ctx, listInsightsVelocity,
		arg.Unit,
		arg.FromTs,
		arg.ToTs,
		arg.FacetKind,
		arg.FacetValue,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListInsightsVelocityRow{}
	for rows.Next() {
		var i ListInsightsVelocityRow
		if err := rows.Scan(&i.Period, &i.Added, &i.Removed); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const pruneInsightsSkillHistory = `-- name: PruneInsightsSkillHistory :execrows
DELETE FROM insights_skill_history
WHERE week_start < $1::date
`

// Drops snapshot rows older than the retention window (~26 weeks), keeping
// the table bounded.
func (q *Queries) PruneInsightsSkillHistory(ctx context.Context, cutoff pgtype.Date) (int64, error) {
	result, err := q.db.Exec(ctx, pruneInsightsSkillHistory, cutoff)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const snapshotInsightsSkillHistory = `-- name: SnapshotInsightsSkillHistory :execrows

INSERT INTO insights_skill_history (skill, week_start, open_count)
SELECT skill, $1::date, open_count
FROM insights_skill_stats
WHERE category = '' AND country = ''
ON CONFLICT (skill, week_start) DO NOTHING
`

// ---------------------------------------------------------------------------
// Skill demand history (the personal GET /me/market-pulse read)
// ---------------------------------------------------------------------------
// Appends this ISO week's global (category=”, country=”) skill open-counts
// to the history table, reading the rollup this same transaction just
// rebuilt rather than re-aggregating jobs. ON CONFLICT DO NOTHING is what
// makes this safe to call on every intra-day rollup-stats run: only the
// first run of a given week actually inserts, every later run this week is
// a no-op.
func (q *Queries) SnapshotInsightsSkillHistory(ctx context.Context, weekStart pgtype.Date) (int64, error) {
	result, err := q.db.Exec(ctx, snapshotInsightsSkillHistory, weekStart)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
